package com.rsd.middle.drawdown;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 提款业务单（阶段 2：单收款人，支付信息直接挂在本单上；阶段 4 多收款人引入 PaymentInstruction 子表，
 * 一个业务单对应多条支付指令、多个成功批次形成多笔借据）。
 * 状态机见 docs/接口契约-阶段2.md §2；"外部已付款成功、中台入账未完成"是显式可恢复状态。
 */
@Entity
@Table(name = "drawdown_order")
public class DrawdownOrder {

    public enum Status { PROCESSING, EXTERNAL_SUCCESS_BOOKING_PENDING, SUCCESS, FAILED, CANCELLED }

    /** 外部付款指令状态（本单一条指令）。 */
    public enum PaymentStatus { TO_SUBMIT, PROCESSING, SUCCESS, FAILED, RESULT_UNCONFIRMED }

    /** 中台入账（Fineract 放款登记）状态。 */
    public enum BookingStatus { NONE, TO_BOOK, BOOKED, RETRY_NEEDED }

    @Id
    private String bizOrderNo;
    private String creditId;
    private String quoteNo;
    private String productId;
    private BigDecimal amount;
    private String payeeName;
    private String payeeAccount;
    private String purpose;

    private Status status;
    private PaymentStatus paymentStatus;
    private String extSerialNo;
    private BookingStatus bookingStatus;
    private Integer bookingRetryCount;
    private String bookingLastError;
    private String loanAccountNo;       // Fineract 借据 id，创建成功即写入（放款前即存在）
    private BigDecimal bookedAmount;    // 实际入账金额
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

    public boolean terminal() {
        return status == Status.SUCCESS || status == Status.FAILED || status == Status.CANCELLED;
    }

    public String getBizOrderNo() { return bizOrderNo; }
    public void setBizOrderNo(String bizOrderNo) { this.bizOrderNo = bizOrderNo; }
    public String getCreditId() { return creditId; }
    public void setCreditId(String creditId) { this.creditId = creditId; }
    public String getQuoteNo() { return quoteNo; }
    public void setQuoteNo(String quoteNo) { this.quoteNo = quoteNo; }
    public String getProductId() { return productId; }
    public void setProductId(String productId) { this.productId = productId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public String getPayeeName() { return payeeName; }
    public void setPayeeName(String payeeName) { this.payeeName = payeeName; }
    public String getPayeeAccount() { return payeeAccount; }
    public void setPayeeAccount(String payeeAccount) { this.payeeAccount = payeeAccount; }
    public String getPurpose() { return purpose; }
    public void setPurpose(String purpose) { this.purpose = purpose; }
    public Status getStatus() { return status; }
    public void setStatus(Status status) { this.status = status; }
    public PaymentStatus getPaymentStatus() { return paymentStatus; }
    public void setPaymentStatus(PaymentStatus paymentStatus) { this.paymentStatus = paymentStatus; }
    public String getExtSerialNo() { return extSerialNo; }
    public void setExtSerialNo(String extSerialNo) { this.extSerialNo = extSerialNo; }
    public BookingStatus getBookingStatus() { return bookingStatus; }
    public void setBookingStatus(BookingStatus bookingStatus) { this.bookingStatus = bookingStatus; }
    public Integer getBookingRetryCount() { return bookingRetryCount; }
    public void setBookingRetryCount(Integer bookingRetryCount) { this.bookingRetryCount = bookingRetryCount; }
    public String getBookingLastError() { return bookingLastError; }
    public void setBookingLastError(String bookingLastError) { this.bookingLastError = bookingLastError; }
    public String getLoanAccountNo() { return loanAccountNo; }
    public void setLoanAccountNo(String loanAccountNo) { this.loanAccountNo = loanAccountNo; }
    public BigDecimal getBookedAmount() { return bookedAmount; }
    public void setBookedAmount(BigDecimal bookedAmount) { this.bookedAmount = bookedAmount; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }
    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(LocalDateTime updatedAt) { this.updatedAt = updatedAt; }
}

package com.rsd.channel;

import com.rsd.channel.ChannelApplicationRecord.BizType;
import com.rsd.channel.ChannelProductRule;
import com.rsd.channel.ChannelProductRuleRepository;
import com.rsd.channel.ChannelApplicationRecordRepository;
import com.rsd.channel.MiddleClient;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;

/**
 * 渠道业务服务：开放条件过滤、字段转换、申请入口、展示状态聚合。
 * 渠道规则（主设计 §四）：企业自助渠道单笔上限 30 万、期限 3/6/12；客户经理渠道上限 100 万、期限同中台。
 * "同一客户换个入口，可选条件不同"由本服务与中台配置差异复现。
 */
@Service
public class ChannelService {

    private final ChannelProductRuleRepository ruleRepo;
    private final ChannelApplicationRecordRepository recordRepo;
    private final MiddleClient middle;

    public ChannelService(ChannelProductRuleRepository ruleRepo, ChannelApplicationRecordRepository recordRepo,
                          MiddleClient middle) {
        this.ruleRepo = ruleRepo;
        this.recordRepo = recordRepo;
        this.middle = middle;
    }

    /** 可选条件：先取中台产品能力，再按渠道规则收窄（金额上限、期限、开放开关）。 */
    @SuppressWarnings("unchecked")
    public Map<String, Object> options(String channelId, String creditId) {
        Map<String, Object> middleOptions = middle.drawdownOptions(creditId);
        List<Map<String, Object>> products = ((List<Object>) middleOptions.get("products")).stream()
                .map(item -> (Map<String, Object>) item)
                .map(p -> narrowByChannel(channelId, p))
                .filter(p -> p != null)
                .toList();
        return Map.of("channelId", channelId, "creditId", creditId, "products", products);
    }

    @SuppressWarnings("unchecked")
    private Map<String, Object> narrowByChannel(String channelId, Map<String, Object> product) {
        return ruleRepo.findByChannelId(channelId).stream()
                .filter(rule -> rule.isEnabled() && rule.getProductId().equals(product.get("productId")))
                .findFirst()
                .map(rule -> {
                    BigDecimal capped = ((BigDecimal) product.get("maxAmount")).min(rule.getMaxAmount());
                    List<Integer> terms = ((List<Integer>) product.get("terms")).stream()
                            .filter(t -> rule.termList().contains(t))
                            .toList();
                    if (terms.isEmpty() || capped.compareTo((BigDecimal) product.get("minAmount")) < 0) {
                        return null; // 渠道开放范围收窄到不可用时直接不透出
                    }
                    return Map.<String, Object>of(
                            "productId", product.get("productId"),
                            "productName", product.get("productName"),
                            "minAmount", product.get("minAmount"),
                            "maxAmount", capped,
                            "terms", terms,
                            "repaymentModes", product.get("repaymentModes"),
                            "availableAmount", product.get("availableAmount"),
                            "channelMaxAmount", rule.getMaxAmount());
                })
                .orElse(null);
    }

    /** 提款申请入口：渠道校验自己的开放规则（金额、期限），转换字段后调用中台。 */
    @SuppressWarnings("unchecked")
    public Map<String, Object> applyDrawdown(String channelId, Map<String, Object> request) {
        String creditId = String.valueOf(request.get("creditId"));
        String productId = String.valueOf(request.get("productId"));
        BigDecimal amount = new BigDecimal(String.valueOf(request.get("amount")));
        int termMonths = Integer.parseInt(String.valueOf(request.get("termMonths")));

        ChannelProductRule rule = ruleRepo.findByChannelId(channelId).stream()
                .filter(r -> r.getProductId().equals(productId) && r.isEnabled())
                .findFirst()
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "PRODUCT_NOT_OPEN"));
        if (amount.compareTo(rule.getMaxAmount()) > 0) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "CHANNEL_AMOUNT_LIMIT");
        }
        if (!rule.termList().contains(termMonths)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "CHANNEL_TERM_LIMIT");
        }

        // 字段转换：渠道语义 → 中台契约（quote → apply 两步，均按 docs/接口契约-阶段2.md）
        Map<String, Object> quote = middle.quote(Map.of(
                "creditId", creditId,
                "productId", productId,
                "amount", amount,
                "termMonths", termMonths,
                "repaymentMode", String.valueOf(request.get("repaymentMode")),
                "firstRepaymentDate", String.valueOf(request.getOrDefault("firstRepaymentDate", ""))));
        Map<String, Object> applied = middle.applyDrawdown(String.valueOf(quote.get("quoteNo")),
                String.valueOf(request.get("payeeName")),
                String.valueOf(request.get("payeeAccount")),
                String.valueOf(request.getOrDefault("purpose", "")));

        String channelRefNo = nextRef();
        saveRecord(channelRefNo, channelId, BizType.DRAWDOWN, String.valueOf(applied.get("bizOrderNo")),
                displayOf(String.valueOf(applied.get("status"))));
        return Map.of("channelRefNo", channelRefNo, "displayStatus", "PROCESSING");
    }

    public Map<String, Object> applyRepayment(String channelId, Map<String, Object> request) {
        Map<String, Object> applied = middle.applyRepayment(
                String.valueOf(request.get("loanAccountNo")),
                String.valueOf(request.get("payerAccount")),
                String.valueOf(request.get("type")),
                new BigDecimal(String.valueOf(request.get("amount"))));
        String channelRefNo = nextRef();
        saveRecord(channelRefNo, channelId, BizType.REPAYMENT, String.valueOf(applied.get("bizOrderNo")),
                displayOf(String.valueOf(applied.get("status"))));
        return Map.of("channelRefNo", channelRefNo, "displayStatus", "PROCESSING");
    }

    /** 结果查询：取中台原始状态，按映射合并为展示状态，同时保存原始状态供追踪。 */
    @SuppressWarnings("unchecked")
    public Map<String, Object> drawdownDetail(String channelRefNo) {
        ChannelApplicationRecord record = requireRecord(channelRefNo, BizType.DRAWDOWN);
        Map<String, Object> middleDetail = middle.drawdownDetail(record.getBizOrderNo());
        String display = displayOf(String.valueOf(middleDetail.get("status")));
        record.setDisplayStatus(display);
        record.setMiddleRawStatus(String.valueOf(middleDetail.get("status")));
        record.setUpdatedAt(LocalDateTime.now().withNano(0));
        recordRepo.save(record);
        return Map.of("channelRefNo", channelRefNo, "displayStatus", display,
                "middleStatus", middleDetail.get("status"), "detail", middleDetail);
    }

    /**
     * 授信申请入口（阶段 3）：渠道做准入（允许发起授信申请的渠道），透传到中台走外部审批。
     * 申请单同时保存渠道侧快照，便于追溯当时从哪个渠道、以什么条件发起。
     */
    public Map<String, Object> applyCredit(String channelId, Map<String, Object> request) {
        if (!channelAllowsCredit(channelId)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "CHANNEL_CREDIT_NOT_OPEN");
        }
        Map<String, Object> applied = middle.applyCredit(request);
        String channelRefNo = nextRef();
        ChannelApplicationRecord record = new ChannelApplicationRecord();
        record.setChannelRefNo(channelRefNo);
        record.setChannelId(channelId);
        record.setBizType(BizType.CREDIT);
        record.setBizOrderNo(String.valueOf(applied.get("bizOrderNo")));
        record.setDisplayStatus("PROCESSING");
        record.setChannelRuleSnapshotJson("{\"channelId\":\"" + channelId + "\",\"entry\":\"credit-application\"}");
        record.setCreatedAt(LocalDateTime.now().withNano(0));
        record.setUpdatedAt(record.getCreatedAt());
        recordRepo.save(record);
        return Map.of("channelRefNo", channelRefNo,
                "bizOrderNo", applied.get("bizOrderNo"),
                "displayStatus", "PROCESSING");
    }

    public Map<String, Object> creditApplicationDetail(String channelRefNo) {
        ChannelApplicationRecord record = recordRepo.findById(channelRefNo)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "APPLICATION_NOT_FOUND"));
        Map<String, Object> middleDetail = middle.creditApplicationDetail(record.getBizOrderNo());
        String display = "APPROVED".equals(String.valueOf(middleDetail.get("status"))) ? "SUCCESS"
                : "REJECTED".equals(String.valueOf(middleDetail.get("status"))) ? "FAILED" : "PROCESSING";
        record.setDisplayStatus(display);
        record.setMiddleRawStatus(String.valueOf(middleDetail.get("status")));
        record.setUpdatedAt(LocalDateTime.now().withNano(0));
        recordRepo.save(record);
        return Map.of("channelRefNo", channelRefNo, "displayStatus", display, "detail", middleDetail);
    }

    /** 渠道准入：阶段 3 两个渠道均允许发起授信申请；规则集中在此便于后续按渠道差异调整。 */
    private boolean channelAllowsCredit(String channelId) {
        return "SELF_SERVICE".equals(channelId) || "RM_ASSISTED".equals(channelId);
    }

    @SuppressWarnings("unchecked")
    public Map<String, Object> repaymentDetail(String channelRefNo) {
        ChannelApplicationRecord record = requireRecord(channelRefNo, BizType.REPAYMENT);
        Map<String, Object> middleDetail = middle.repaymentDetail(record.getBizOrderNo());
        String display = displayOf(String.valueOf(middleDetail.get("status")));
        record.setDisplayStatus(display);
        record.setMiddleRawStatus(String.valueOf(middleDetail.get("status")));
        record.setUpdatedAt(LocalDateTime.now().withNano(0));
        recordRepo.save(record);
        return Map.of("channelRefNo", channelRefNo, "displayStatus", display, "detail", middleDetail);
    }

    /**
     * 展示状态映射（契约 §2）：中台 PROCESSING / EXTERNAL_SUCCESS_BOOKING_PENDING 等处理中状态
     * 对外统一展示"PROCESSING"；成功与失败直传。映射关系保留在 record.middleRawStatus。
     */
    private String displayOf(String middleStatus) {
        return switch (middleStatus) {
            case "SUCCESS", "FAILED" -> middleStatus;
            default -> "PROCESSING"; // PROCESSING / EXTERNAL_SUCCESS_BOOKING_PENDING / 其他处理中状态
        };
    }

    private void saveRecord(String channelRefNo, String channelId, BizType type, String bizOrderNo, String display) {
        ChannelApplicationRecord record = new ChannelApplicationRecord();
        record.setChannelRefNo(channelRefNo);
        record.setChannelId(channelId);
        record.setBizType(type);
        record.setBizOrderNo(bizOrderNo);
        record.setDisplayStatus(display);
        record.setCreatedAt(LocalDateTime.now().withNano(0));
        record.setUpdatedAt(record.getCreatedAt());
        recordRepo.save(record);
    }

    private ChannelApplicationRecord requireRecord(String channelRefNo, BizType type) {
        return recordRepo.findById(channelRefNo)
                .filter(record -> record.getBizType() == type)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "APPLICATION_NOT_FOUND"));
    }

    private String nextRef() {
        return "CHN-%06d".formatted(ThreadLocalRandom.current().nextInt(1000000));
    }
}

